CREATE TABLE `paiements` (
  `id` int(10) UNSIGNED NOT NULL,
  `client_id` int(10) UNSIGNED NOT NULL,
  `trajet_id` int(10) UNSIGNED NOT NULL,
  `montant` decimal(10,2) NOT NULL,
  `statut` varchar(20) NOT NULL DEFAULT 'en_attente',
  `mode` varchar(10) NOT NULL DEFAULT 'cash',
  `stripe_payment_id` varchar(100) DEFAULT NULL,
  `date_creation` datetime NOT NULL DEFAULT current_timestamp(),
  `date_confirmation` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `routes` (
  `id` int(11) NOT NULL,
  `from_city_id` int(11) NOT NULL,
  `to_city_id` int(11) NOT NULL,
  `price_per_person` decimal(10,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

